 const packages={},terminals=[];for(const[name,x,y,w,h,d,count]of[['ESP32',-2.4,10,6,6,.9,48],['W25Q32',4.5,4,4.8,4.1,1.2,8],['ESPPSRAM64H',-4,-1,4.8,4.1,1.2,8],['CH552T',1,-10,6.5,4.3,1.2,20],['BM8563',-6,-10,3,3,1.1,8],['TP4057',-6,-15,2.8,1.6,.9,6]]){const q=slab(host.body,w,h,d,.07,[x,y,-d],dark,[],.005);q.name='TimerCamera-X own schematic '+name+' fixed body,inferred installed envelope';packages[name]=q;if(name==='ESP32'){for(const axis of[0,1])for(const sign of[-1,1])for(let i=0;i<12;i++){const at=(i-5.5)*.46;terminals.push(mesh(host.body,new THREE.BoxGeometry(axis?.25:.38,axis?.38:.25,.13),metal,[x+(axis?at:sign*(w/2+.1)),y+(axis?sign*(h/2+.1):at),-.05],'TimerCamera-X own QFN48 actual four-sided terminal'));}}else for(const sign of[-1,1])for(let i=0;i<count/2;i++)terminals.push(mesh(host.body,new THREE.BoxGeometry(.38,.3,.13),metal,[x+sign*(w/2+.1),y+(i-(count/2-1)/2)*Math.min(.5,h/(count/2)),-.05],'TimerCamera-X actual retained '+name+' terminal'));}
 const antenna=slab(host.body,18.6,6.1,.85,.15,[0,18.5,-.85],materials.metal(0x989e96),[],.01);antenna.name='TimerCamera-X own rear photo actual retained upper antenna carrier';const regulators=[],regulatorTerminals=[];for(const[name,x,y]of[['SY8089AAC',-6,-6],['HX6306P152',-7,-18],['HX6306P282',6,-18]]){const q=slab(host.body,2.5,1.6,.7,.06,[x,y,1],dark,[],.005);q.name='TimerCamera-X own '+name+' fixed package';regulators.push(q);for(const sign of[-1,1])for(let i=0;i<3;i++)regulatorTerminals.push(mesh(host.body,new THREE.BoxGeometry(.3,.24,.1),metal,[x+sign*1.25,y+(i-1)*.5,1.02],'TimerCamera-X retained regulator termination'));}
