 const fpcSocket=slab(host.body,18,3,1.3,.1,[0,-6,1],materials.plastic(0xe3e5da),[],.01);fpcSocket.name='TimerCamera-X own03 actual front FPC receiving carrier';const fpcContacts=[];for(let i=0;i<24;i++)fpcContacts.push(mesh(host.body,new THREE.BoxGeometry(.28,2.3,.12),metal,[(i-11.5)*.65,-6,2.3],'TimerCamera-X actual24camera FPC retained contacts'));const flex=slab(host.body,8,11,.12,.1,[0,1,2.3],materials.plastic(0xb75c18),[],0);flex.name='TimerCamera-X own03 camera polyimide flex,inferred installation';const cameraSupports=[];for(const x of[-5,5])for(const y of[5,15])cameraSupports.push(cylinder(host.body,.8,.4,[x,y,1.2],dark,'TimerCamera-X actual fixed camera carrier post,inferred envelope'));const sensorBoard=slab(host.body,13,14,.65,.35,[0,10,1.4],dark,[],.01),sensor=slab(host.body,6.5,6,.6,.1,[0,10,2.05],dark,[],.01);sensorBoard.name='TimerCamera-X own03 actual fixed camera carrier';sensor.name='TimerCamera-X actual passive OV3660 sensor envelope';
