function usb(host){const frame=new THREE.Group();frame.name='TimerCamera-X actual USB-C receiving frame';frame.position.fromArray(spec.usb.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const metal=materials.metal(0xb7beb5),dark=materials.plastic(0x232921),shape=capsule(8.9,3.3);shape.holes.push(capsule(8.2,2.6,{path:new THREE.Path(),clockwise:true}));const shield=solid(frame,shape,6,[0,0,-6],metal,'TimerCamera-X actual hollow USB-C metal shield'),back=mesh(frame,new THREE.BoxGeometry(8.1,2.5,.5),dark,[0,0,-5.75],'TimerCamera-X actual USB-C deep backing'),tongue=mesh(frame,new THREE.BoxGeometry(6,.65,4),dark,[0,0,-3.5],'TimerCamera-X actual USB-C receiving tongue'),contacts=[],feet=[];for(const sign of[-1,1])for(let i=0;i<12;i++)contacts.push(mesh(frame,new THREE.BoxGeometry(.18,.06,2.8),materials.metal(0xc4ad74),[(i-5.5)*.5,sign*.355,-3.5],'TimerCamera-X real24USB-C receiving contacts'));for(const x of[-4,4])feet.push(mesh(host.body,new THREE.BoxGeometry(.55,1.4,.25),metal,[x,-19.1,1.125],'TimerCamera-X actual retained USB-C board anchor'));const port=host.add(new Port({id:'usb',label:'USB-C',connector:'usb-c',position:spec.usb.position,quaternion:portQuaternion('bottom'),hitSize:[8.9,1,3.3],meta:{role:'visual-connector',face:'bottom',scope:'Actual receiving shell/contact geometry only;no USB data or charging'}}));return{frame,shield,back,tongue,contacts,feet,port};}
