function controls(host){const dark=materials.plastic(0x293027),metal=materials.metal(0xaeb4aa),fixed=[],terminals=[];const powerBody=slab(host.body,2.6,3,1.5,.12,[-10.2,-14.7,-2.1],materials.plastic(0xb69a29),[],.01);powerBody.name='TimerCamera-X own07 actual fixed yellowPWR package';fixed.push(powerBody);const resetBody=slab(host.body,2.2,2.4,.5,.1,[8.59675,13.72261,1],dark,[],.01);resetBody.name='TimerCamera-X own03 actual fixed reset switch package';fixed.push(resetBody);for(const sign of[-1,1]){terminals.push(mesh(host.body,new THREE.BoxGeometry(.35,1,.6),metal,[-10.2+sign*.9,-14.7,-.3],'TimerCamera-X fixedPWR termination reachesPCB'));terminals.push(mesh(host.body,new THREE.BoxGeometry(.35,1,.1),metal,[8.59675+sign*.9,13.72261,1.02],'TimerCamera-X fixedRESET termination atPCB'));}
 const pmesh=new THREE.Mesh(new THREE.BoxGeometry(.6,1.6,.35),materials.plastic(0xc7c6b7));pmesh.name='TimerCamera-X actual sidePWR plunger only';const power=host.add(new Button({id:'power',label:'PWR/WAKE · actual side plunger intent',position:spec.power.position,axis:spec.power.axis,travel:spec.power.travelMm,mesh:pmesh,meta:{scope:'Cap-only momentary intent;no power/RTC/wake/firmware state',travelInferred:true}}));const rmesh=new THREE.Group();mesh(rmesh,new THREE.CylinderGeometry(.34,.34,.28,32).rotateX(Math.PI/2),materials.plastic(0x818b80),[0,0,0],'TimerCamera-X actual recessedRESET cap');mesh(rmesh,new THREE.CylinderGeometry(.17,.17,.4,24).rotateX(Math.PI/2),dark,[0,0,-.25],'TimerCamera-X actual movingRESET stem');rmesh.name='TimerCamera-X actual needle-access reset moving plunger only';const reset=host.add(new Button({id:'reset',label:'RESET · actual pin-access momentary intent',position:spec.reset.position,axis:spec.reset.axis,travel:spec.reset.travelMm,mesh:rmesh,meta:{scope:'Actual tiny native front aperture;cap/stem only,no reset protocol or firmware effect',travelInferred:true}}));return{fixed,terminals,power,reset};}
