export function buildTimerCameraX(host,{mount='none'}={}){if(!spec.configurationSchema.mount.values.includes(mount))throw new RangeError('Unknown TimerCamera-X mount');const parts=addCadParts(host,data.filter(d=>['front','rear'].includes(d.role)),{shell:materials.plastic(0x30332e,{roughness:.86})}),boardParts=board(host),batteryParts=battery(host),input=grove(host),usbParts=usb(host),optical=optics(host),fixing=fixings(host),buttons=controls(host),indicator=status(host);const camera=host.add(new Component({id:'camera',label:'OV3660 passive66.5degree optical frame',position:spec.camera.position,meta:{role:'visual-anchor',sensor:'OV3660',documentaryFovDeg:66.5,scope:'Passive optical reference;no frames/video/AI/camera protocol'}}));const rearMount=host.add(new Port({id:'mount',label:'TimerCamera-X own static rear mounting receiver',connector:spec.mount.connector,position:spec.mount.position,quaternion:portQuaternion('back'),hitSize:[24,1,32],meta:{role:'visual-connector',face:'back',scope:'One whole static own native support;neutral shape identity,no articulated hinge'}}));const film=slab(host.body,...spec.label.size,.04,.55,spec.label.position,materials.plastic(0xe8e9e3,{roughness:.8}),[],0);film.name='TimerCamera-X real own rear manufacturer adhesive substrate';film.userData={role:'physical-label-substrate',face:'back',inferredThicknessMm:.04};host.timerCameraXAssembly={parts,board:boardParts,battery:batteryParts,grove:input,usb:usbParts,optics:optical,fixings:fixing,controls:buttons,status:indicator,camera,film,mount:rearMount};host.unitStickers=addStickers(host);if(mount!=='none')rearMount.attach(mount==='two-ear'?new TwoEarMount():new TwinHoleMount());}
